class Solution:
    def validWordSquare(self, words: List[str]) -> bool:
        for i, word in enumerate(words):
            for j, c in enumerate(word):
                # Bounds first — avoids IndexError on words[j][i]
                if j >= len(words) or i >= len(words[j]) or c != words[j][i]:
                    return False
        return True

